// Pins androidx.work:work-runtime-ktx to the WorkManager everything else resolves (2.8.1).
//
// expo-widgets pulls androidx.glance, which still asks for work-runtime-ktx 2.7.1, while the
// rest of the graph resolves work-runtime 2.8.1. From 2.8 the Kotlin extensions moved INTO
// work-runtime (ktx is an empty artifact), so mixing 2.7.1-ktx with 2.8.1 ships the same
// classes twice and :app:checkDebugDuplicateClasses fails (OneTimeWorkRequestKt,
// PeriodicWorkRequestKt).
//
// android/ is generated by prebuild, so this lives in a config plugin rather than a hand edit.
const { withProjectBuildGradle } = require('expo/config-plugins');

const WORK = '2.8.1';
const MARK = '// zekra: work-runtime-ktx pin';
const BLOCK = `
${MARK}
allprojects {
  configurations.configureEach {
    resolutionStrategy.force "androidx.work:work-runtime-ktx:${WORK}"
  }
}
`;

module.exports = function withAndroidWorkManager(config) {
  return withProjectBuildGradle(config, (cfg) => {
    if (!cfg.modResults.contents.includes(MARK)) cfg.modResults.contents += BLOCK;
    return cfg;
  });
};
